// applyEmphasis replaces the first __...__ pair with <strong> tags and the
// first _..._ pair with <em> tags, matching the behavior of the original
// implementation.
func applyEmphasis(markdown string) string {
	markdown = replaceFirstPair(markdown, "__", "<strong>", "</strong>")
	markdown = replaceFirstPair(markdown, "_", "<em>", "</em>")
	return markdown
}

// replaceFirstPair replaces the first occurrence of open with the opening tag
// and the next occurrence of open with the closing tag.
func replaceFirstPair(s, marker, open, close string) string {
	if i := strings.Index(s, marker); i >= 0 {
		s = s[:i] + open + s[i+len(marker):]
		if j := strings.Index(s, marker); j >= 0 {
			s = s[:j] + close + s[j+len(marker):]
		}
	}
	return s
}
```

